solutions.better:
class Solution:
    def superPow(self, a: int, b: list[int]) -> int:
        mod = 1337
        exp = 0
        for digit in b:
            exp = exp * 10 + digit
        ans, base = 1, a % mod
        while exp:
            if exp & 1:
                ans = (ans * base) % mod
            base = (base * base) % mod
            exp >>= 1
        return ans

