class Solution:
    def superPow(self, a: int, b: list[int]) -> int:
        mod = 1337
        def mod_pow(x, e):
            res = 1
            x %= mod
            while e:
                if e & 1:
                    res = (res * x) % mod
                x = (x * x) % mod
                e >>= 1
            return res
        ans = 1
        for digit in b:
            ans = (mod_pow(ans, 10) * mod_pow(a, digit)) % mod
        return ans

